// Product library and issued client documents are stored separately from the active calculation.
const LIB_KEY='izdelie-library-v2',QUOTES_KEY='izdelie-quotes-v2',DRAFT_KEY='izdelie-quote-draft-v2',COMPANY_KEY='izdelie-company-v2';
const uid=()=>crypto.randomUUID(),today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Vladivostok'}).format(new Date()),stamp=()=>new Date().toISOString();
const readJSON=(k,fallback)=>{try{return JSON.parse(localStorage.getItem(k)||'null')??fallback}catch{return fallback}};
function writeJSON(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Недостаточно места в браузере. Скачайте резервную копию базы.');return false}}
function cleanCalculation(s){if(!validState(s))throw Error('Некорректный формат расчёта');const c={...blank()};c.engineVersion=s.engineVersion||CostEngine.VERSION;c.version=s.lines.some(l=>l.processKey)?3:(s.version===3?3:s.version===2?2:1);c.schemaVersion=c.version;for(const k of ['name','code','client','type','qty','scope','notes','overhead','transport','markup','vat','profitTax'])c[k]=s[k]??(k==='profitTax'?25:c[k]);if(s.installationSpec!==undefined)c.installationSpec=structuredClone(s.installationSpec);if(s.productImage)c.productImage=s.productImage;c.markupBase=s.markupBase??'cost';c.projectName=typeof s.projectName==='string'?s.projectName:'';c.clientNotes=typeof s.clientNotes==='string'?s.clientNotes:'';c.lines=s.lines.map(l=>({id:l.production?l.id:uid(),...Object.fromEntries(['materialType','production','processKey','processPosition','processMetrics','processBinding','processOutput','basePrice','baseUnit','sourceFormula','sourceParameters','sourceFinalCost','physicalQuantity','physicalUnit','productivity','productivityUnit','productivityStatus','unitChangeNotice','workshop','productionOrder'].filter(k=>l[k]!==undefined).map(k=>[k,structuredClone(l[k])])),...(l.installation!==undefined?{installation:l.installation}:{}),operation:l.operation?structuredClone(l.operation):undefined,sheetWidth:Number.isFinite(l.sheetWidth)?l.sheetWidth:null,sheetLength:Number.isFinite(l.sheetLength)?l.sheetLength:null,estimate:l.estimate&&Number.isFinite(l.estimate.rate)&&l.estimate.rate>0?{rate:l.estimate.rate,mass:l.mass,grade:String(l.estimate.grade||''),note:String(l.estimate.note||'')}:null,costCategory:l.costCategory==='design'?'design':'',catalogId:typeof l.catalogId==='string'?l.catalogId:'',name:l.name,unit:l.unit,group:l.group,kind:l.kind,qty:l.qty,price:l.price,reserve:l.reserve,pack:l.pack,scope:l.scope,allocation:l.allocation,confirmed:l.confirmed===true,deliveryIncluded:l.deliveryIncluded===true,date:typeof l.date==='string'?l.date:'',source:typeof l.source==='string'?l.source:'Импорт JSON',mass:Number.isFinite(l.mass)&&l.mass>=0?l.mass:null}));if(s.archive&&typeof CalculationArchive!=='undefined'&&s.archive.signature===CalculationArchive.signature(s)){c.archive=structuredClone(s.archive);c.archive.signature=CalculationArchive.signature(c);}return c}
function library(){const a=readJSON(LIB_KEY,[]);return Array.isArray(a)?a.filter(e=>e&&/^[a-zA-Z0-9-]+$/.test(e.id)&&Array.isArray(e.revisions)&&e.revisions.length&&e.revisions.every(r=>r&&validState(r.calculation))):[]}
function quoteHistoryRecords(){const a=readJSON(QUOTES_KEY,[]);return Array.isArray(a)?a.filter(q=>q&&/^[a-zA-Z0-9-]+$/.test(q.id)&&q.document&&Array.isArray(q.document.items)):[]}
function companyProfile(){const c=readJSON(COMPANY_KEY,{});return {name:typeof c.name==='string'?c.name:'',contacts:typeof c.contacts==='string'?c.contacts:'',details:typeof c.details==='string'?c.details:'',signer:typeof c.signer==='string'?c.signer:''}}
function newQuoteDraft(){return {id:uid(),number:'КП-'+today().replaceAll('-','')+'-'+String(quoteHistoryRecords().length+1).padStart(3,'0'),date:today(),validUntil:'',subject:'Коммерческое предложение',client:state.client||'',contact:'',payment:'',delivery:'',leadtime:'',warranty:'',comment:'',discount:0,items:[]}}
let quoteDraft=readJSON(DRAFT_KEY,null),issuedView=null;
if(!quoteDraft||!Array.isArray(quoteDraft.items)||!quoteDraft.items.every(x=>x&&validState(x.calculation)&&/^[a-zA-Z0-9-]+$/.test(x.id)))quoteDraft=newQuoteDraft();
function saveDraft(){return writeJSON(DRAFT_KEY,quoteDraft)}
function qset(k,v){quoteDraft[k]=v;saveDraft();refreshQuoteTotal()}
function qitem(id,k,v){const l=quoteDraft.items.find(x=>x.id===id);if(!l)return;l[k]=v;saveDraft();refreshQuoteTotal()}
function keepCurrent(){if(!writeJSON('izdelie-recovery',state))return false;return true}
function migrateSnapshots(){if(readJSON('izdelie-snapshots-migrated-v2',false))return;const a=readJSON('izdelie-snapshots',[]);if(!Array.isArray(a))return;const lib=library();for(const s of a){if(!validState(s))continue;const calc=cleanCalculation(s),date=s.updated||stamp();lib.push({id:uid(),name:calc.name,code:calc.code,type:calc.type,createdAt:date,updatedAt:date,revisions:[{id:uid(),date,calculation:calc}]})}if(writeJSON(LIB_KEY,lib))writeJSON('izdelie-snapshots-migrated-v2',true)}
function saveCalculation(){if(state.engineVersion&&!(CostEngine.SUPPORTED_VERSIONS||[CostEngine.VERSION]).includes(state.engineVersion)){toast('Эта версия методики доступна только для просмотра архива');return}if(!validState(state)){toast('Исправьте размер партии и параметры расчёта перед сохранением');return}const lib=library(),existing=lib.find(e=>e.id===state.libraryId),r=CostEngine.calculate(state);modal('Сохранить изделие в базу',`<p class="subtitle">${esc(state.name)} · ${esc(state.code)||'без артикула'} · ${dec(state.qty)} шт.</p><div class="note ${r.partial?'':'info'}" style="margin-top:18px">${r.partial?'Расчёт неполный. Он будет сохранён как черновик, с неизвестными объёмами и ставками.':'Сохранится состав, ставки, объёмы и параметры цены. Последующие правки не изменят эту версию.'}</div><div class="mini-actions"><button class="primary" onclick="commitCalculation(${existing?'false':'true'})">${existing?'Сохранить новую версию v'+(existing.revisions.length+1):'Сохранить новое изделие'}</button>${existing?'<button onclick="commitCalculation(true)">Сохранить отдельным изделием</button>':''}</div>`)}
function commitCalculation(asNew){if(state.engineVersion&&!(CostEngine.SUPPORTED_VERSIONS||[CostEngine.VERSION]).includes(state.engineVersion)){toast('Эта версия методики доступна только для просмотра архива');return}const lib=library(),calc=CalculationArchive.capture(cleanCalculation(state));let entry=!asNew&&lib.find(x=>x.id===state.libraryId);if(!entry){entry={id:uid(),name:calc.name,code:calc.code,type:calc.type,createdAt:stamp(),revisions:[]};lib.unshift(entry)}Object.assign(entry,{name:calc.name,code:calc.code,type:calc.type,updatedAt:stamp()});entry.revisions.push({id:uid(),date:stamp(),calculation:calc});if(!writeJSON(LIB_KEY,lib))return;state.libraryId=entry.id;persist();$('modal').close();toast('Изделие сохранено · версия '+entry.revisions.length);if(page===7)renderLibrary()}
function recoverCalculation(){const old=readJSON('izdelie-recovery',null);if(!validState(old)){toast('Восстановительной копии нет');return}if(!keepCurrent())return;state=cleanCalculation(old);persist();go(0);toast('Предыдущий расчёт восстановлен')}
function renderLibrary(){migrateSnapshots();$('app').innerHTML=title('Библиотека производства','База расчётов изделий','Сохраняйте состав и нормы, создавайте версии и собирайте коммерческие предложения.','Сохранённые записи')+`<div class="toolbar"><button class="primary" onclick="saveCalculation()">＋ Сохранить текущий расчёт</button><button onclick="libraryImportDialog()">↑ Импорт расчётов</button><button onclick="exportLibrary()">↓ Резервная копия</button>${validState(readJSON('izdelie-recovery',null))?'<button onclick="recoverCalculation()">Восстановить предыдущий расчёт</button>':''}</div><div class="card"><div class="toolbar"><input id="libSearch" placeholder="Название изделия, артикул или тип" oninput="libraryRows()"><select id="libFilter" onchange="libraryRows()"><option value="">Все расчёты</option><option value="ready">Без пропусков</option><option value="draft">С пропусками</option></select></div><p class="small" id="libCount"></p><div id="libRows"></div></div><div class="note info">База сохраняется локально и синхронизируется с сервером при подключении. Статус и полная резервная копия доступны в разделе «Сервер и копии». JSON переносит изделия и версии отдельно. Исходный архив Excel остаётся в справочниках и не считается готовой базой изделий.</div>`;libraryRows()}
function libraryRows(){const q=($('libSearch')?.value||'').toLowerCase(),f=$('libFilter')?.value||'',lib=library().filter(e=>{const c=e.revisions.at(-1).calculation,r=CalculationArchive.result(c);return (e.name+' '+e.code+' '+e.type+' '+(c.projectName||'')).toLowerCase().includes(q)&&(!f||(f==='draft'?r.partial:!r.partial))});$('libCount').textContent=`Найдено ${lib.length} изделий · показано ${Math.min(lib.length,100)}`;$('libRows').innerHTML=lib.length?`<div class="tablewrap"><table><thead><tr><th>Изделие</th><th>Версии / дата</th><th>Партия</th><th class="number">Цена / шт. с НДС</th><th>Статус</th><th></th></tr></thead><tbody>${lib.slice(0,100).map(e=>{const c=e.revisions.at(-1).calculation,r=CalculationArchive.result(c);return `<tr><td class="rowname">${esc(e.name)}<span class="source">${esc(e.code)||'Без артикула'} · ${esc(e.type)}</span><span class="source">${esc(c.projectName||'Без проекта')}</span></td><td>v${e.revisions.length}<span class="source">${dateText(e.updatedAt)}</span></td><td>${c.qty} шт.</td><td class="number">${r.partial?'—':money(r.unit)}</td><td><span class="badge ${r.partial?'warning':''}">${r.partial?'Есть пропуски':'Предварительный'}</span></td><td><div class="row-actions"><button class="iconbtn" onclick="libraryDetail('${e.id}')">Версии</button><button class="iconbtn" onclick="openLibrary('${e.id}',${e.revisions.length-1},true)">Копия</button><button class="iconbtn" onclick="addLibraryToQuote('${e.id}')">＋ В КП</button></div></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty"><b>Здесь будут ваши изделия</b>Сохраните текущий расчёт или импортируйте ранее скачанные JSON-файлы.<br>Наличие пропусков не мешает хранить черновик.</div>'}
function dateText(d){const x=new Date(d.length===10?d+'T12:00:00':d);return Number.isFinite(+x)?x.toLocaleDateString('ru-RU'):esc(d)}
function libraryDetail(id){const e=library().find(x=>x.id===id);if(!e)return;modal('Версии · '+e.name,`<p class="small">Открытие версии сохранит текущий расчёт как временную восстановительную копию.</p>${e.revisions.map((v,i)=>{const r=CalculationArchive.result(v.calculation);return `<div class="version-row"><div><b>Версия ${i+1}</b><span class="source">${dateText(v.date)} · ${v.calculation.qty} шт. · ${r.partial?'известная часть ':''}${money(r.unit)} / шт.</span></div><div class="row-actions"><button onclick="openLibrary('${id}',${i},false)">Открыть</button><button onclick="openLibrary('${id}',${i},true)">Создать копию</button><button onclick="addLibraryToQuote('${id}',${i})">В КП</button></div></div>`}).join('')}`)}
function openLibrary(id,index,copy){const e=library().find(x=>x.id===id),v=e?.revisions[index];if(!v||!keepCurrent())return;state=cleanCalculation(v.calculation);if(!copy)state.libraryId=e.id;else {state.name+=' — копия';state.client=''}persist();$('modal').close();go(0);toast(copy?'Создана копия расчёта':'Открыта версия '+(index+1))}
function exportLibrary(){download('izdelie-base-'+today()+'.json',JSON.stringify({format:'izdelie-library',version:2,exportedAt:stamp(),entries:library()},null,2),'application/json');toast('Резервная копия содержит внутренние данные')}
let pendingLibraryImport=[];
function libraryImportDialog(){pendingLibraryImport=[];modal('Импорт расчётов в базу',`<p class="subtitle">Поддерживаются JSON одного расчёта, массив расчётов и резервная копия базы «Изделие». Можно выбрать несколько файлов. Текущая база сохранится.</p><div class="field" style="margin-top:20px"><label for="libFiles">Файлы JSON</label><input id="libFiles" type="file" accept=".json,application/json" multiple onchange="prepareLibraryImport(event)"></div><div id="libImportPreview"></div>`)}
async function prepareLibraryImport(e){pendingLibraryImport=[];try{for(const file of e.target.files){if(file.size>20e6)throw Error('Файл больше 20 МБ: '+file.name);const data=JSON.parse(await file.text());if(data?.format==='izdelie-library'&&data.version===2&&Array.isArray(data.entries)){for(const entry of data.entries){if(!Array.isArray(entry.revisions)||!entry.revisions.length)throw Error('В изделии отсутствуют версии');const revisions=entry.revisions.map(v=>({id:uid(),date:typeof v.date==='string'?v.date:stamp(),calculation:cleanCalculation(v.calculation)})),c=revisions.at(-1).calculation;pendingLibraryImport.push({id:uid(),name:c.name,code:c.code,type:c.type,createdAt:stamp(),updatedAt:stamp(),revisions,origin:String(entry.id||''),file:file.name})}}else{const calculations=Array.isArray(data)?data:[data];for(const s of calculations){const c=cleanCalculation(s);pendingLibraryImport.push({id:uid(),name:c.name,code:c.code,type:c.type,createdAt:stamp(),updatedAt:stamp(),revisions:[{id:uid(),date:stamp(),calculation:c}],origin:'',file:file.name})}}}if(pendingLibraryImport.length>2000)throw Error('Слишком много изделий за один импорт');$('libImportPreview').innerHTML=`<div class="note info">К добавлению: ${pendingLibraryImport.length} изделий. Существующие записи не перезаписываются. Повторный импорт добавляет отдельные копии.</div><div class="catalog-results"><table><thead><tr><th>Изделие</th><th>Артикул</th><th>Версий</th><th>Файл</th></tr></thead><tbody>${pendingLibraryImport.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.code)}</td><td>${x.revisions.length}</td><td>${esc(x.file)}</td></tr>`).join('')}</tbody></table></div><button class="primary" onclick="commitLibraryImport()" ${!pendingLibraryImport.length?'disabled':''}>Добавить в базу</button>`}catch(err){pendingLibraryImport=[];$('libImportPreview').innerHTML=`<div class="note">Импорт не выполнен: ${esc(err.message)}. Проверьте, что это JSON расчёта «Изделие».</div>`}}
function commitLibraryImport(){if(!pendingLibraryImport.length)return;const entries=pendingLibraryImport.map(({file,origin,...e})=>e),lib=library();if(!writeJSON(LIB_KEY,[...entries,...lib]))return;pendingLibraryImport=[];$('modal').close();go(7);toast('Расчёты добавлены в базу')}
function companyDialog(){const c=companyProfile();modal('Реквизиты для коммерческого предложения',`<form onsubmit="saveCompany(event)">${[['Название компании','name',2],['Контакты: телефон, почта, сайт','contacts',2],['Реквизиты и адрес','details',4],['Подписант / должность','signer',2]].map(([label,k,rows])=>`<div class="field"><label for="company-${k}">${label}</label><textarea id="company-${k}" rows="${rows}">${esc(c[k])}</textarea></div>`).join('')}<p class="small">Реквизиты сохраняются для новых КП. Сохранённые версии предложений не изменятся.</p><button class="primary" type="submit">Сохранить реквизиты</button></form>`)}
function saveCompany(e){e.preventDefault();const c={};for(const k of ['name','contacts','details','signer'])c[k]=$('company-'+k).value.trim();if(!writeJSON(COMPANY_KEY,c))return;$('modal').close();render();toast('Реквизиты сохранены')}
function quoteFromCurrent(){if(!validState(state)){toast('Исправьте параметры текущего расчёта');return}addQuoteCalculation(state,'current-'+(state.libraryId||state.code||state.name));go(8)}
function calculationFingerprint(c){const v={...c};delete v.updated;delete v.libraryId;delete v.archive;delete v.draftId;v.lines=c.lines.map(({id,...l})=>l);return documentFingerprint(v)}
function addQuoteCalculation(calc,key){const normalized=cleanCalculation(calc);const signature=calculationFingerprint(normalized);const existing=quoteDraft.items.find(x=>x.key===key||calculationFingerprint(x.calculation)===signature);if(existing){toast('Изделие уже есть в КП. Измените его количество в таблице.');return}const c=normalized;quoteDraft.items.push({id:uid(),key,calculation:c,name:c.name,description:c.scope,qty:c.qty,override:null});if(!quoteDraft.client)quoteDraft.client=c.client;saveDraft();toast('Изделие добавлено в предложение')}
function addLibraryToQuote(id,index){const e=library().find(x=>x.id===id);if(!e)return;const v=e.revisions[index??e.revisions.length-1];if(!v)return;addQuoteCalculation(v.calculation,id+'-'+v.id);$('modal').close();go(8)}
function quotePicker(){modal('Добавить изделие из базы',`<div class="toolbar"><input id="quoteProductSearch" placeholder="Поиск изделия или артикула" oninput="quotePickerRows()"></div><div class="catalog-results" id="quoteProducts"></div><button onclick="$('modal').close();go(7)">Открыть базу изделий</button>`);quotePickerRows()}
function quotePickerRows(){const q=$('quoteProductSearch').value.toLowerCase(),a=library().filter(e=>(e.name+' '+e.code).toLowerCase().includes(q));$('quoteProducts').innerHTML=a.length?`<table><thead><tr><th>Изделие</th><th>Версия</th><th></th></tr></thead><tbody>${a.slice(0,100).map(e=>`<tr><td>${esc(e.name)}<span class="source">${esc(e.code)}</span></td><td>v${e.revisions.length}</td><td><button onclick="addLibraryToQuote('${e.id}')">＋ Добавить</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Изделий пока нет. Сохраните расчёт в базу или добавьте текущий расчёт прямо в КП.</div>'}
function resetQuote(){modal('Новое коммерческое предложение',`<p class="subtitle">Текущий черновик будет заменён. Ранее сохранённые версии остаются в реестре.</p><div class="mini-actions"><button onclick="exportDraftBackup()">Скачать текущий черновик</button><button class="primary" onclick="quoteDraft=newQuoteDraft();saveDraft();$('modal').close();go(8)">Создать новое КП</button></div>`)}
function removeQuoteItem(id){quoteDraft.items=quoteDraft.items.filter(x=>x.id!==id);saveDraft();renderQuote()}
function exportDraftBackup(){download('kp-draft-'+today()+'.json',JSON.stringify({format:'izdelie-quote-draft',version:2,draft:quoteDraft,company:companyProfile()},null,2),'application/json');toast('Черновик содержит внутренние расчёты. Не отправляйте его заказчику.')}
function renderQuote(){const c=companyProfile(),q=quoteDraft;const input=(label,k,type='text')=>`<div class="field"><label for="q-${k}">${label}</label><input id="q-${k}" type="${type}" value="${esc(q[k])}" oninput="qset('${k}',${type==='number'?"this.value===''?null:+this.value":'this.value'})" ${type==='number'?'min="0" max="100" step="0.1"':''}></div>`;const area=(label,k)=>`<div class="field"><label for="q-${k}">${label}</label><textarea id="q-${k}" rows="2" oninput="qset('${k}',this.value)">${esc(q[k])}</textarea></div>`;
 $('app').innerHTML=title('Продажи / Конструктор КП','Коммерческое предложение','Соберите позиции, укажите условия и сохраните неизменяемую версию для выдачи.','Черновик')+`<div class="toolbar"><button onclick="resetQuote()">＋ Новое КП</button><button onclick="companyDialog()">Реквизиты компании</button><button onclick="go(9)">Реестр предложений →</button><button onclick="exportDraftBackup()">↓ Черновик JSON</button><button onclick="importDraftDialog()">↑ Открыть черновик</button></div><div class="layout quote-layout"><section><div class="card"><div class="cardhead"><h2>Карточка предложения</h2><span class="small">${esc(c.name)||'Компания ещё не указана'}</span></div><div class="grid3">${input('Номер КП','number')}${input('Дата предложения','date','date')}${input('Действует до','validUntil','date')}</div>${input('Заголовок','subject')}<div class="grid2">${input('Заказчик / организация','client')}${input('Контактное лицо','contact')}</div></div><div class="card"><div class="cardhead"><h2>Изделия в предложении</h2><div class="row-actions"><button onclick="quoteFromCurrent()">＋ Текущий расчёт</button><button class="primary" onclick="quotePicker()">＋ Из базы</button></div></div><p class="small">Количество пересчитывает калькуляцию партии, включая подготовку и округление закупки. Ставки фиксируются на момент добавления изделия. Для обновления удалите позицию и добавьте нужную версию заново.</p>${q.items.length?q.items.map((l,i)=>`<div class="quote-item"><div class="cardhead"><h3>${i+1}. ${esc(l.calculation.code)||'Изделие'}</h3><button class="iconbtn" onclick="removeQuoteItem('${l.id}')" aria-label="Удалить позицию ${i+1}">Удалить</button></div><div class="field"><label for="qi-name-${l.id}">Название для заказчика</label><input id="qi-name-${l.id}" value="${esc(l.name)}" oninput="qitem('${l.id}','name',this.value)"></div><div class="field"><label for="qi-desc-${l.id}">Комплектация / описание для заказчика</label><textarea id="qi-desc-${l.id}" rows="2" oninput="qitem('${l.id}','description',this.value)">${esc(l.description)}</textarea></div><div class="grid2"><div class="field"><label for="qi-qty-${l.id}">Количество, шт.</label><input id="qi-qty-${l.id}" type="number" min="1" step="1" value="${esc(l.qty)}" oninput="qitem('${l.id}','qty',this.value===''?null:+this.value)"></div><div class="field"><label for="qi-price-${l.id}">Своя цена с НДС до скидки, ₽ / шт.</label><input id="qi-price-${l.id}" type="number" min="0" step="0.01" value="${esc(l.override)}" placeholder="По калькуляции" oninput="qitem('${l.id}','override',this.value===''?null:+this.value)"><span class="hint">Пусто — использовать расчётную цену.</span></div></div><div id="qi-total-${l.id}" class="note info"></div></div>`).join(''):'<div class="empty"><b>Добавьте первое изделие</b>Выберите расчёт из базы или текущую калькуляцию.</div>'}</div><div class="card"><h2>Коммерческие условия</h2><div class="grid2">${area('Порядок оплаты','payment')}${area('Срок изготовления / выполнения','leadtime')}${area('Доставка и монтаж','delivery')}${area('Гарантия','warranty')}</div>${area('Дополнительные условия для заказчика','comment')}${input('Скидка на позиции, %','discount','number')}<p class="small">Для КП цена за единицу округляется до копеек, затем умножается на количество. Итог может немного отличаться от неокруглённой внутренней калькуляции.</p></div></section><section><div class="summary" id="quoteTotal"></div></section></div>`;refreshQuoteTotal()}
function refreshQuoteTotal(){if(!$('quoteTotal'))return;const t=BusinessCore.quoteTotals(quoteDraft,CostEngine.calculate);$('quoteTotal').innerHTML=`<div class="eyebrow">Предложение заказчику</div><div class="big">${money(t.total)}</div><div class="small">${t.rows.length} позиций · с НДС</div><div class="divider"></div><div class="metricline"><span>В том числе НДС</span><b>${money(t.tax)}</b></div><div class="note ${t.errors.length?'':'info'}">${t.errors.length?'Расчёт неполный. Исправьте замечания ниже перед сохранением версии.':t.preliminary?'Предварительное КП: остаются несогласованные нормы или даты цен.':'Суммы заполнены. Проверьте комплектность и условия предложения.'}</div>${t.errors.slice(0,8).map(e=>`<div class="issue">${esc(e)}</div>`).join('')}<div class="mini-actions"><button onclick="previewDraft()">Предпросмотр</button><button class="primary" onclick="issueQuote()">Сохранить версию КП</button></div><p class="small">Версия появится в реестре. HTML и печать / PDF содержат только клиентские данные.</p>`;t.rows.forEach(l=>{const el=$('qi-total-'+l.id);if(el)el.innerHTML=`Цена: <b>${money(l.unit)}</b> / шт. · сумма <b>${money(l.total)}</b> с НДС ${dec(l.vat)}%${Number.isFinite(l.unit)&&l.unit/(1+l.vat/100)<l.result.costUnit?'<br><span class="warning">Цена после скидки ниже расчётной себестоимости.</span>':''}`})}
function isISODate(v){return typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v}
function quoteValidation(){const q=quoteDraft,c=companyProfile(),errors=[...BusinessCore.quoteTotals(q,CostEngine.calculate).errors];if(!c.name.trim())errors.push('Заполните название компании в реквизитах');if(!q.client.trim())errors.push('Укажите заказчика');if(!q.number.trim())errors.push('Укажите номер предложения');if(!q.subject.trim())errors.push('Укажите заголовок предложения');if(!isISODate(q.date))errors.push('Укажите корректную дату предложения');if(q.validUntil&&(!isISODate(q.validUntil)||q.validUntil<q.date))errors.push('Срок действия не может быть раньше даты предложения');if(!q.payment.trim())errors.push('Укажите порядок оплаты');if(!q.leadtime.trim())errors.push('Укажите срок изготовления');if(!q.delivery.trim())errors.push('Укажите условия доставки и монтажа');q.items.forEach((l,i)=>{if(!l.name.trim())errors.push('Позиция '+(i+1)+': нет названия')});return errors}
function issueQuote(){const errors=quoteValidation();if(errors.length){modal('Перед сохранением КП',`<div class="note">${errors.map(esc).join('<br>')}</div><div class="mini-actions"><button onclick="$('modal').close()">Вернуться к заполнению</button><button onclick="companyDialog()">Реквизиты компании</button></div>`);return}const h=quoteHistoryRecords(),version=1+Math.max(0,...h.filter(x=>x.document.number===quoteDraft.number).map(x=>x.version)),record={id:uid(),draftId:quoteDraft.id,version,createdAt:stamp(),status:'saved',document:BusinessCore.publicDocument(quoteDraft,companyProfile(),CostEngine.calculate)};h.unshift(record);if(!writeJSON(QUOTES_KEY,h))return;issuedView=record.id;go(10);toast('КП сохранено · версия '+version)}
function previewDraft(){const t=BusinessCore.quoteTotals(quoteDraft,CostEngine.calculate);if(t.errors.length){toast('Для предпросмотра заполните объёмы и ставки всех позиций');return}issuedView={document:BusinessCore.publicDocument(quoteDraft,companyProfile(),CostEngine.calculate),version:null,status:'draft'};go(10)}
function getIssued(){return typeof issuedView==='object'?issuedView:quoteHistoryRecords().find(x=>x.id===issuedView)}
function clientQuoteHTML(d,version){return `<article class="document quote-document">${CJBrand.logoHTML()}<div class="dochead"><div><strong>${esc(d.company.name)||'Компания не указана'}</strong><div class="small multiline">${esc(d.company.contacts)}</div></div><div class="small">№ ${esc(d.number)}${version?' · версия '+version:''}<br>от ${dateText(d.date)}${d.validUntil?'<br>Действует до '+dateText(d.validUntil):''}</div></div><h1>${esc(d.subject)}</h1><p><span class="muted">Заказчик:</span> ${esc(d.client)}${d.contact?'<br><span class="muted">Контакт:</span> '+esc(d.contact):''}</p>${d.preliminary?'<span class="tag">Предварительное предложение</span>':''}<div class="tablewrap"><table class="quote-table"><thead><tr><th>№</th><th>Наименование и комплектация</th><th class="number">Кол-во</th><th class="number">Цена с НДС, ₽</th><th class="number">Сумма с НДС, ₽</th></tr></thead><tbody>${d.items.map(l=>`<tr><td>${l.position}</td><td><strong>${esc(l.name)}</strong>${l.code?'<span class="source">'+esc(l.code)+'</span>':''}<div class="small multiline">${esc(l.description)}</div>${productImageHTML(l.productImage)}${l.limitations?'<div class="small multiline">'+esc(l.limitations)+'</div>':''}<span class="source">НДС ${dec(l.vat)}%</span></td><td class="number">${l.qty} шт.</td><td class="number">${money(l.unit)}</td><td class="number">${money(l.total)}</td></tr>`).join('')}</tbody></table></div><div class="total"><span>Итого с НДС</span><strong>${money(d.total)}</strong></div><div class="metricline"><span>В том числе НДС</span><b>${money(d.tax)}</b></div><div class="quote-terms">${[['Оплата',d.terms.payment],['Срок изготовления',d.terms.leadtime],['Доставка и монтаж',d.terms.delivery],['Гарантия',d.terms.warranty],['Дополнительные условия',d.terms.comment]].filter(x=>x[1]).map(([n,v])=>`<div class="term-row"><strong>${n}</strong><div class="multiline">${esc(v)}</div></div>`).join('')}</div>${d.preliminary?'<div class="note">Предложение предварительное. Комплектность, производственные нормы и актуальность цен требуют согласования.</div>':''}${d.company.details?'<div class="divider"></div><div class="small multiline">'+esc(d.company.details)+'</div>':''}${d.company.signer?'<div class="signature">'+esc(d.company.signer)+'</div>':''}</article>`}
function renderIssued(){const record=getIssued();if(!record){go(9);return}const d=record.document;$('app').innerHTML=title(record.version?'Сохранённое предложение':'Предпросмотр черновика',esc(d.number),record.version?'Цены, условия и реквизиты зафиксированы в этой версии.':'Предпросмотр ещё не сохранён в реестре.',record.version?'Версия '+record.version:'Черновик')+`<div class="toolbar print-hide"><button onclick="go(8)">← Конструктор КП</button><button onclick="go(9)">Реестр</button><button class="primary" onclick="window.print()">Печать / Сохранить PDF</button><button onclick="downloadQuote()">↓ Клиентский HTML</button>${!record.version?'<button onclick="issueQuote()">Сохранить версию</button>':''}</div>`+clientQuoteHTML(d,record.version)}
function downloadQuote(id){const record=id?quoteHistoryRecords().find(x=>x.id===id):getIssued();if(!record)return;const d=record.document,css=`body{font:13px Arial,sans-serif;color:#262626;margin:0;background:white}.document{max-width:900px;margin:40px auto;padding:35px}h1{font-size:28px;margin:35px 0 20px}.dochead,.metricline,.total{display:flex;justify-content:space-between;gap:20px;margin:18px 0}.dochead strong{font-size:18px}table{width:100%;border-collapse:collapse;margin-top:28px}th{font-size:10px;color:#595959;text-align:left;background:#F2F2F2}td,th{padding:12px 8px;border-bottom:1px solid #BFBFBF;vertical-align:top}.number{text-align:right;white-space:nowrap}.small,.source{font-size:11px;color:#595959;line-height:1.7}.source{display:block}.multiline{white-space:pre-wrap;overflow-wrap:anywhere}.total{font-size:23px;border-top:2px solid;padding-top:22px}.term-row{display:grid;grid-template-columns:150px 1fr;gap:15px;margin:15px 0;line-height:1.7}.quote-terms{margin:28px 0}.note{background:#f7f1e7;color:#8d6f40;padding:15px;line-height:1.7}.tag{display:inline-block;color:#8d6f40;background:#f7f1e7;padding:6px 12px;border-radius:20px;font-size:11px}.divider{border-top:1px solid #BFBFBF;margin:25px 0}.signature{margin-top:30px}.muted{color:#595959}.tools{text-align:center;padding:20px}@page{size:A4;margin:16mm 12mm}@media print{.tools{display:none}.document{margin:0;padding:0;max-width:none}thead{display:table-header-group}tr,.term-row,.total{break-inside:avoid}.total{font-size:21px}}@media(max-width:600px){.document{padding:18px;margin:0}.tablewrap{overflow:auto}.term-row{display:block}.dochead{display:block}}`;
 const html='<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(d.number)+' · '+esc(d.company.name)+'</title><style>'+css+'</style></head><body><div class="tools"><button onclick="window.print()">Печать / Сохранить PDF</button></div>'+clientQuoteHTML(d,record.version)+'</body></html>';download('KP-'+d.number.replace(/[^a-zA-Zа-яА-Я0-9-]/g,'')+'-v'+(record.version||'draft')+'.html',html,'text/html;charset=utf-8');toast('Скачан клиентский документ без внутренней калькуляции')}
function renderQuoteHistory(){$('app').innerHTML=title('Продажи / Реестр','Коммерческие предложения','Сохранённые версии содержат зафиксированные цены и условия.','Сохранённые записи')+`<div class="toolbar"><button class="primary" onclick="go(8)">Конструктор КП</button><button onclick="exportQuoteHistory()">↓ Резервная копия реестра</button><button onclick="importQuoteHistoryDialog()">↑ Восстановить реестр</button></div><div class="card"><div class="toolbar"><input id="quoteHistorySearch" placeholder="Номер КП, заказчик или изделие" oninput="quoteHistoryRows()"><select id="quoteHistoryStatus" onchange="quoteHistoryRows()"><option value="">Все статусы</option><option value="saved">Сохранено</option><option value="sent">Отправлено</option><option value="accepted">Согласовано</option><option value="declined">Отклонено</option></select></div><div id="quoteHistoryRows"></div></div><p class="small">Статус меняется вручную и не отправляет предложение заказчику. HTML или PDF передаются заказчику отдельно. Сохранённые документы синхронизируются с сервером при подключении; статус доступен в разделе «Сервер и копии». Скачивайте резервные копии.</p>`;quoteHistoryRows()}
function quoteHistoryRows(){const q=($('quoteHistorySearch')?.value||'').toLowerCase(),s=$('quoteHistoryStatus')?.value||'',a=quoteHistoryRecords().filter(x=>(x.document.number+' '+x.document.client+' '+x.document.items.map(i=>i.name).join(' ')).toLowerCase().includes(q)&&(!s||x.status===s));$('quoteHistoryRows').innerHTML=a.length?`<div class="tablewrap"><table><thead><tr><th>Предложение</th><th>Заказчик</th><th class="number">Сумма с НДС</th><th>Статус</th><th></th></tr></thead><tbody>${a.map(x=>`<tr><td><b>${esc(x.document.number)}</b><span class="source">v${x.version} · ${dateText(x.createdAt)} · ${x.document.items.length} позиций</span></td><td>${esc(x.document.client)}</td><td class="number">${money(x.document.total)}</td><td><select aria-label="Статус ${esc(x.document.number)} версия ${x.version}" onchange="updateQuoteStatus('${x.id}',this.value)">${[['saved','Сохранено'],['sent','Отправлено'],['accepted','Согласовано'],['declined','Отклонено']].map(([v,l])=>`<option value="${v}" ${x.status===v?'selected':''}>${l}</option>`).join('')}</select></td><td><div class="row-actions"><button class="iconbtn" onclick="issuedView='${x.id}';go(10)">Открыть / PDF</button><button class="iconbtn" onclick="downloadQuote('${x.id}')">HTML</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><b>Предложений пока нет</b>Соберите КП в конструкторе и сохраните его версию.</div>'}
function updateQuoteStatus(id,status){if(!['saved','sent','accepted','declined'].includes(status))return;const a=quoteHistoryRecords(),x=a.find(q=>q.id===id);if(x){x.status=status;x.updatedAt=stamp();if(writeJSON(QUOTES_KEY,a))toast('Статус обновлён')}}
function documentFingerprint(d){const stable=x=>Array.isArray(x)?x.map(stable):x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,stable(x[k])])):x;return JSON.stringify(stable(d))}
function exportQuoteHistory(){download('kp-registry-'+today()+'.json',JSON.stringify({format:'izdelie-quote-history',version:2,quotes:quoteHistoryRecords()},null,2),'application/json')}
function importDraftDialog(){modal('Открыть черновик КП',`<p class="small">Текущий черновик будет заменён после проверки файла. Реквизиты компании из файла также восстановятся. Реестр сохранённых КП останется прежним.</p><input type="file" accept=".json" onchange="importQuoteDraft(event)">`)}
async function importQuoteDraft(e){try{const f=e.target.files[0];if(!f||f.size>20e6)throw Error('Неподходящий размер файла');const x=JSON.parse(await f.text());if(x.format!=='izdelie-quote-draft'||x.version!==2||!x.draft||!Array.isArray(x.draft.items))throw Error('Требуется резервная копия черновика КП');const d=newQuoteDraft();for(const k of ['number','date','validUntil','subject','client','contact','payment','delivery','leadtime','warranty','comment']){if(typeof x.draft[k]!=='string')throw Error('Некорректное поле '+k);d[k]=x.draft[k]}if(!Number.isFinite(x.draft.discount)||x.draft.discount<0||x.draft.discount>100)throw Error('Некорректная скидка');d.discount=x.draft.discount;d.items=x.draft.items.map(i=>{if(typeof i.name!=='string'||typeof i.description!=='string'||!Number.isInteger(i.qty)||i.qty<1||!(i.override===null||Number.isFinite(i.override)&&i.override>=0))throw Error('Некорректная позиция КП');return {id:uid(),key:uid(),name:i.name,description:i.description,qty:i.qty,override:i.override,calculation:cleanCalculation(i.calculation)}});const c={};for(const k of ['name','contacts','details','signer']){if(typeof x.company?.[k]!=='string')throw Error('Некорректные реквизиты');c[k]=x.company[k]}if(!writeJSON(DRAFT_KEY,d))return;quoteDraft=d;writeJSON(COMPANY_KEY,c);$('modal').close();go(8);toast('Черновик восстановлен')}catch(err){toast('Не удалось открыть: '+err.message)}}
function importQuoteHistoryDialog(){modal('Восстановить реестр КП',`<p class="small">Выберите JSON резервной копии реестра. Документы добавятся к существующим; повторные идентичные версии пропускаются.</p><input type="file" accept=".json" onchange="importQuoteHistory(event)">`)}
async function importQuoteHistory(e){try{const f=e.target.files[0];if(!f||f.size>20e6)throw Error('Неподходящий размер файла');const x=JSON.parse(await f.text());if(x.format!=='izdelie-quote-history'||x.version!==2||!Array.isArray(x.quotes))throw Error('Требуется резервная копия реестра');const a=quoteHistoryRecords(),keys=new Set(a.map(r=>r.document.number+'|'+r.version+'|'+documentFingerprint(r.document)));let added=0;for(const r of x.quotes){const d=r.document;if(!d||!Array.isArray(d.items)||!d.items.length||!d.company||!d.terms||!Number.isInteger(r.version)||r.version<1)throw Error('Повреждённая версия КП');for(const k of ['number','date','validUntil','subject','client','contact'])if(typeof d[k]!=='string')throw Error('Некорректное поле КП');for(const k of ['name','contacts','details','signer'])if(typeof d.company[k]!=='string')throw Error('Некорректные реквизиты');for(const k of ['payment','delivery','leadtime','warranty','comment'])if(typeof d.terms[k]!=='string')throw Error('Некорректные условия');const doc={number:d.number,date:d.date,validUntil:d.validUntil,subject:d.subject,client:d.client,contact:d.contact,company:{name:d.company.name,contacts:d.company.contacts,details:d.company.details,signer:d.company.signer},terms:{payment:d.terms.payment,delivery:d.terms.delivery,leadtime:d.terms.leadtime,warranty:d.terms.warranty,comment:d.terms.comment},items:d.items.map((i,n)=>{if(typeof i.name!=='string'||typeof i.code!=='string'||typeof i.description!=='string'||typeof i.limitations!=='string'||!Number.isInteger(i.qty)||i.qty<1||['unit','total','vat','tax'].some(k=>!Number.isFinite(i[k])||i[k]<0)||Math.abs(BusinessCore.round(i.unit*i.qty)-i.total)>.01||Math.abs(BusinessCore.round(i.total-i.total/(1+i.vat/100))-i.tax)>.01)throw Error('Некорректные суммы позиции');return {...(DomainSchema.productImage(i.productImage)?{productImage:i.productImage}:{}),position:n+1,name:i.name,code:i.code,description:i.description,qty:i.qty,unit:i.unit,total:i.total,vat:i.vat,tax:i.tax,limitations:i.limitations}}),total:d.total,tax:d.tax,preliminary:d.preliminary===true};if(!Number.isFinite(d.total)||!Number.isFinite(d.tax)||Math.abs(BusinessCore.round(doc.items.reduce((s,i)=>s+i.total,0))-doc.total)>.01||Math.abs(BusinessCore.round(doc.items.reduce((s,i)=>s+i.tax,0))-doc.tax)>.01)throw Error('Итог не совпадает с позициями');const key=doc.number+'|'+r.version+'|'+documentFingerprint(doc);if(!keys.has(key)){a.push({id:uid(),version:r.version,createdAt:typeof r.createdAt==='string'?r.createdAt:stamp(),status:['saved','sent','accepted','declined'].includes(r.status)?r.status:'saved',document:doc});keys.add(key);added++}}if(!writeJSON(QUOTES_KEY,a))return;$('modal').close();go(9);toast('Добавлено версий: '+added)}catch(err){toast('Реестр не изменён: '+err.message)}}




